"""
MemoryNote: Basic memory unit with LLM-generated metadata.

Based on A-mem (Agentic Memory) paper: https://arxiv.org/pdf/2502.12110
"""

import json
import re
import uuid
from datetime import datetime
from typing import Any, Dict, List, Optional, TYPE_CHECKING

if TYPE_CHECKING:
    try:
        from .llm_controller import LLMController
    except ImportError:
        from llm_controller import LLMController


# JSON schema for metadata extraction
METADATA_SCHEMA = {
    "type": "json_schema",
    "json_schema": {
        "name": "response",
        "schema": {
            "type": "object",
            "properties": {
                "keywords": {
                    "type": "array",
                    "items": {"type": "string"}
                },
                "context": {
                    "type": "string",
                },
                "tags": {
                    "type": "array",
                    "items": {"type": "string"}
                },
            },
            "required": ["keywords", "context", "tags"],
            "additionalProperties": False
        },
        "strict": True
    }
}


METADATA_PROMPT = """Generate a structured analysis of the following content by:
1. Identifying the most salient keywords (focus on nouns, verbs, and key concepts)
2. Extracting core themes and contextual elements
3. Creating relevant categorical tags

Format the response as a JSON object:
{
    "keywords": [
        // several specific, distinct keywords that capture key concepts and terminology
        // Order from most to least important
        // Don't include keywords that are the name of the speaker or time
        // At least three keywords, but don't be too redundant.
    ],
    "context":
        // one sentence summarizing:
        // - Main topic/domain
        // - Key arguments/points
        // - Intended audience/purpose
    ,
    "tags": [
        // several broad categories/themes for classification
        // Include domain, format, and type tags
        // At least three tags, but don't be too redundant.
    ]
}

Content for analysis:
"""


class MemoryNote:
    """
    Basic memory unit with metadata.

    Each memory note contains:
    - content: The raw content/observation
    - keywords: LLM-extracted keywords for retrieval
    - context: LLM-generated summary/context
    - tags: Categorical tags for classification
    - links: Connected memory IDs (Zettelkasten-style)
    - timestamps: Creation and access times
    - evolution_history: Track of how memory evolved

    Metadata can be:
    1. Auto-generated by LLM if llm_controller is provided
    2. Manually specified via constructor
    3. Updated later through evolution process
    """

    def __init__(
        self,
        content: str,
        id: Optional[str] = None,
        keywords: Optional[List[str]] = None,
        links: Optional[List[int]] = None,
        importance_score: Optional[float] = None,
        retrieval_count: Optional[int] = None,
        timestamp: Optional[str] = None,
        last_accessed: Optional[str] = None,
        context: Optional[str] = None,
        evolution_history: Optional[List] = None,
        category: Optional[str] = None,
        tags: Optional[List[str]] = None,
        llm_controller: Optional["LLMController"] = None,
        auto_generate_metadata: bool = True
    ):
        """
        Initialize a memory note.

        Args:
            content: The memory content (required)
            id: Unique identifier (auto-generated if not provided)
            keywords: Keywords for retrieval
            links: Connected memory IDs
            importance_score: Memory importance (default 1.0)
            retrieval_count: How often this memory was retrieved
            timestamp: Creation timestamp
            last_accessed: Last access timestamp
            context: Contextual summary
            evolution_history: History of changes
            category: Memory category
            tags: Classification tags
            llm_controller: LLM controller for metadata generation
            auto_generate_metadata: Whether to auto-generate missing metadata
        """
        self.content = content

        # Generate metadata using LLM if controller provided and metadata is missing
        if (llm_controller and auto_generate_metadata and
            any(param is None for param in [keywords, context, tags])):
            analysis = self._analyze_content(content, llm_controller)
            keywords = keywords or analysis.get("keywords", [])
            context = context or analysis.get("context", "General")
            tags = tags or analysis.get("tags", [])

        # Set default values
        self.id = id or str(uuid.uuid4())
        self.keywords = keywords or []
        self.links = links or []
        self.importance_score = importance_score or 1.0
        self.retrieval_count = retrieval_count or 0

        current_time = datetime.now().strftime("%Y%m%d%H%M")
        self.timestamp = timestamp or current_time
        self.last_accessed = last_accessed or current_time

        # Handle context that can be either string or list
        self.context = context or "General"
        if isinstance(self.context, list):
            self.context = " ".join(self.context)

        self.evolution_history = evolution_history or []
        self.category = category or "Uncategorized"
        self.tags = tags or []

    @staticmethod
    def _analyze_content(content: str, llm_controller: "LLMController") -> Dict[str, Any]:
        """
        Analyze content to extract keywords, context, and tags using LLM.

        This is where the LLM generates semantic metadata for the memory,
        which enables better retrieval and linking.

        Args:
            content: Text content to analyze
            llm_controller: LLM controller for API calls

        Returns:
            Dict with keywords, context, and tags
        """
        prompt = METADATA_PROMPT + content

        try:
            response = llm_controller.get_completion(
                prompt,
                response_format=METADATA_SCHEMA
            )

            # Clean response and parse JSON
            response = re.sub(r'^```json\s*|\s*```$', '', response, flags=re.MULTILINE).strip()
            analysis = json.loads(response)
            return analysis

        except json.JSONDecodeError as e:
            print(f"JSON parsing error in analyze_content: {e}")
            return {"keywords": [], "context": "General", "tags": []}
        except Exception as e:
            print(f"Error analyzing content: {e}")
            return {"keywords": [], "context": "General", "tags": []}

    def to_dict(self) -> Dict[str, Any]:
        """Convert memory note to dictionary."""
        return {
            "id": self.id,
            "content": self.content,
            "keywords": self.keywords,
            "context": self.context,
            "tags": self.tags,
            "links": self.links,
            "importance_score": self.importance_score,
            "retrieval_count": self.retrieval_count,
            "timestamp": self.timestamp,
            "last_accessed": self.last_accessed,
            "category": self.category,
            "evolution_history": self.evolution_history
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "MemoryNote":
        """Create memory note from dictionary."""
        return cls(
            content=data["content"],
            id=data.get("id"),
            keywords=data.get("keywords"),
            links=data.get("links"),
            importance_score=data.get("importance_score"),
            retrieval_count=data.get("retrieval_count"),
            timestamp=data.get("timestamp"),
            last_accessed=data.get("last_accessed"),
            context=data.get("context"),
            evolution_history=data.get("evolution_history"),
            category=data.get("category"),
            tags=data.get("tags"),
            auto_generate_metadata=False  # Don't regenerate when loading
        )

    def __repr__(self) -> str:
        return f"MemoryNote(id={self.id[:8]}..., content={self.content[:50]}...)"
